INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(40311, 'Nehemiah 5:1', 'Nehemiah', 5, 1, 'په دې وخت کې زیات شورماشور جوړ شو. ډېرو خلکو او د هغوی ښځو د نورو یهودیانو په ضد شکایت پیل کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah5_verse_1.mp3', '', 1761754199, 1761754199),
(40312, 'Nehemiah 5:2', 'Nehemiah', 5, 2, 'ځینو وویل: «زمونږ کورنۍ ډېرې لویې دي، نو مونږ غلو دانو ته اړتیا لرو ترڅو ژوندي پاتې شو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah5_verse_2.mp3', '', 1761754199, 1761754199),
(40313, 'Nehemiah 5:3', 'Nehemiah', 5, 3, 'نورو وویل: «مونږ مجبور یو چې خپل پټي، د انګورو باغونه او خپل کورونه ګرو کړو، ترڅو د دې قحطۍ په وخت کې په پوره اندازه غلې دانې په بیه واخلو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah5_verse_3.mp3', '', 1761754199, 1761754199),
(40314, 'Nehemiah 5:4', 'Nehemiah', 5, 4, 'نورو وویل: «مونږ مجبور شو چې پاچا ته د خپلو پټیو او انګورو د باغونو د مالیې د ورکولو دپاره پیسې پور کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah5_verse_4.mp3', '', 1761754199, 1761754199),
(40315, 'Nehemiah 5:5', 'Nehemiah', 5, 5, 'مونږ لکه د نورو یهودیانو په شان د یو قوم څخه یو. زمونږ اولادونه هم د هغوی د اولادونو په شان دي. خو مونږ مجبور یو چې خپل اولادونه غلامان کړو او زمونږ د لورګانو څخه ځینې لا پخوا د وینځو په توګه خرڅې شوې دي. مونږ بې وسه یو، ځکه چې زمونږ پټي او د انګورو باغونه ګرو شوي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah5_verse_5.mp3', '', 1761754199, 1761754199),
(40316, 'Nehemiah 5:6', 'Nehemiah', 5, 6, 'کله چې ما د هغوی شکایتونه او تورونه واورېدل، ډېر په قهر شوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah5_verse_6.mp3', '', 1761754199, 1761754199),
(40317, 'Nehemiah 5:7', 'Nehemiah', 5, 7, 'د فکر کولو نه وروسته ما د قوم مشران او مامورین ملامته کړل او هغوی ته مې وویل: «تاسو ولې د خپلو خپلوانو څخه سود اخلئ؟» بیا مې د هغوی په ضد لویه جرګه راوغوښتله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah5_verse_7.mp3', '', 1761754199, 1761754199),
(40318, 'Nehemiah 5:8', 'Nehemiah', 5, 8, 'هغوی ته مې وویل: «ترڅو پورې چې مونږ کولای شول، خپل یهودي خپلوان مو چې په پردیو قومونو باندې خرڅ شوي وو، بېرته واخیستل. اوس تاسو هغوی دې ته مجبوروئ چې خپل ځانونه په مونږ، یعنې په خپلو خلکو باندې خرڅ کړي!» مشران غلي شول او ځواب یې نه درلود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah5_verse_8.mp3', '', 1761754199, 1761754199),
(40319, 'Nehemiah 5:9', 'Nehemiah', 5, 9, 'بیا مې وویل: «تاسو چې کوم کار کوئ هغه ښه نه دی! تاسو باید د خدای څخه ووېرېږئ او هغه کار وکړئ چې ښه وي. نو تاسو باید زمونږ دښمنانو یعنې غیریهودیانو ته وخت ورنه کړئ چې په مونږ باندې ملنډې ووهي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah5_verse_9.mp3', '', 1761754199, 1761754199),
(40320, 'Nehemiah 5:10', 'Nehemiah', 5, 10, 'ما، زما خپلوانو او زما ملګرو، خلکو ته پیسې او غلې دانې په پور ورکړې دي، خو مونږ باید د هغو په بدل کې سود ونه غواړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah5_verse_10.mp3', '', 1761754199, 1761754199),
(40321, 'Nehemiah 5:11', 'Nehemiah', 5, 11, 'تاسو چې د هغوی پټي، د انګورو باغونه، د زیتونو باغونه او کورونه او هم هغه سود چې د پیسو، غلو دانو، شرابو او د زیتونو د تېلو په خاطر د هغوی څخه اخیستی دی، همدا نن بېرته ورکړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah5_verse_11.mp3', '', 1761754199, 1761754199),
(40322, 'Nehemiah 5:12', 'Nehemiah', 5, 12, 'مشرانو ځواب ورکړ: «څنګه چې تاسو وایئ هماغسې به وکړو. مونږ به د هغوی جایداد بېرته ورکړو او خپل پورونه به ورڅخه نه غواړو.» کاهنان مې راوغوښتل او د هغوی په مخکې مې مشرانو او مامورینو ته قسم ورکړ چې په هغې وعدې باندې چې همدا اوس یې وکړه، ټینګ ودریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah5_verse_12.mp3', '', 1761754199, 1761754199),
(40323, 'Nehemiah 5:13', 'Nehemiah', 5, 13, 'بیا مې څادر راوویست او هغه مې وڅنډه. بیا مې وویل: «ستاسو څخه هرڅوک چې په خپله وعده باندې ونه درېده، نو خدای به هغه همداسې وڅنډي. هغه به ستاسو څخه ستاسو کورونه او ټول شیان واخلي او تاسو ته به هېڅ شی پرېنږدي.» هرڅوک چې حاضر ؤ، ویې ویل: «آمین!» او د څښتن ثنا یې وویله. څنګه چې خلکو وعده وکړه، هماغسې یې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah5_verse_13.mp3', '', 1761754199, 1761754199),
(40324, 'Nehemiah 5:14', 'Nehemiah', 5, 14, 'د دې ټولو دولسو کالو په دوران کې چې زه د یهودا والي وم، یعنې د ارتخششتا د پاچاهۍ د شلم کال څخه تر دوه دېرشم کاله پورې نه ما او نه زما خپلوانو د والي دپاره هغه ټاکل شوې ډوډۍ خوړله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah5_verse_14.mp3', '', 1761754199, 1761754199),
(40325, 'Nehemiah 5:15', 'Nehemiah', 5, 15, 'زما څخه مخکې هر والي به په خلکو باندې دروند بار ایښوده، یعنې د هغوی څخه به یې د خوړو او شرابو دپاره د ورځې څلوېښت د سپینو زرو سکې غوښتلې. حتی د هغوی مامورینو به په خلکو باندې ظلم کاوه. خو ما داسې کار نه کاوه، ځکه چې د خدای څخه وېرېدم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah5_verse_15.mp3', '', 1761754199, 1761754199),
(40326, 'Nehemiah 5:16', 'Nehemiah', 5, 16, 'ما خپل ټول قوت او طاقت د دېوال په بیا ودانولو باندې ولګاوه او هېڅ ځمکه مې د ځان دپاره وانخیستله. زما ټول خدمتګاران هلته د کار دپاره راټول شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah5_verse_16.mp3', '', 1761754199, 1761754199),
(40327, 'Nehemiah 5:17', 'Nehemiah', 5, 17, 'برسېره پر هغو ټولو خلکو چې د شاوخوا قومونو څخه به ماته راتلل، ما تل د یهودیانو یو سلو پنځوسو کسانو او د هغوی مامورینو ته په خپل دسترخوان باندې ډوډۍ ورکوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah5_verse_17.mp3', '', 1761754199, 1761754199),
(40328, 'Nehemiah 5:18', 'Nehemiah', 5, 18, 'ما به هره ورځ یو غویی، شپږ چاغ پسونه، چرګان او په هرو لسو ورځو کې به مې یوځل په زیاته اندازه هر ډول شراب تیارول. ما د والي په توګه د خپلو خوړو د لګښت غوښتنه نه ده کړې. زه پوهېدم چې دا په خلکو باندې څومره دروند بار دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah5_verse_18.mp3', '', 1761754199, 1761754199),
(40329, 'Nehemiah 5:19', 'Nehemiah', 5, 19, 'ای زما خدایه، ما در په یاد کړه او د هغه څه په خاطر چې د دې خلکو دپاره مې کړي دي ماته برکت راکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah5_verse_19.mp3', '', 1761754199, 1761754199),
(40330, 'Judges 13:1', 'Judges', 13, 1, 'اسراییلیانو یوځل بیا د څښتن په وړاندې ګناه وکړه. نو څښتن فلسطینیان پرېښودل چې څلوېښت کاله په هغوی باندې حکومت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_1.mp3', '', 1761754199, 1761754199),
(40331, 'Judges 13:2', 'Judges', 13, 2, 'په هغه وخت کې د زرعه په ښارګوټي کې یو سړی اوسېده چې نوم یې مانوح ؤ او د دان د قبیلې څخه ؤ. د هغه ښځه شنډه وه او اولاد یې نه درلود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_2.mp3', '', 1761754199, 1761754199),
(40332, 'Judges 13:3', 'Judges', 13, 3, 'یوه ورځ د څښتن فرښته هغې ښځې ته ښکاره شوه او ورته ویې ویل: «ته شنډه او بې اولاده یې. خو زر به امیدواره شې او زوی به وزېږوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_3.mp3', '', 1761754199, 1761754199),
(40333, 'Judges 13:4', 'Judges', 13, 4, 'پام کوه چې هېڅ شراب ونه څښې او حرام شیان ونه خورې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_4.mp3', '', 1761754199, 1761754199),
(40334, 'Judges 13:5', 'Judges', 13, 5, 'کله چې ستا زوی وشو، نو هېڅکله باید د هغه ویښتان ونه خرایې، ځکه چې هغه به د زېږېدلو د ورځې څخه د نذر په توګه خدای ته وقف شي. هغه به اسراییل د فلسطینیانو څخه وژغوري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_5.mp3', '', 1761754199, 1761754199),
(40335, 'Judges 13:6', 'Judges', 13, 6, 'بیا هغه ښځه خپل مېړه ته ورغله او ورته ویې ویل: «ماته د خدای یو نبي راغی. هغه د خدای د فرښتې په شان ښکاره کېده او ډېر هیبتناک ؤ. ما د هغه څخه دا پوښتنه ونه کړه چې ته د کوم ځای څخه راغلی یې او هغه هم ماته خپل نوم ونه ښوده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_6.mp3', '', 1761754199, 1761754199),
(40336, 'Judges 13:7', 'Judges', 13, 7, 'خو هغه راته وویل چې ته به امیدواره شې او یو زوی به وزېږوې. شراب به نه څښې او حرام شیان به نه خورې، ځکه چې دا هلک به د زېږېدلو د وخت څخه نیولې د مرګ تر ورځې پورې د نذر په توګه څښتن ته وقف وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_7.mp3', '', 1761754199, 1761754199),
(40337, 'Judges 13:8', 'Judges', 13, 8, 'بیا مانوح څښتن ته دعا وکړه او ویې ویل: «ای څښتنه، زه تاته سوال کوم، هغه نبي چې تا رالېږلی ؤ هغه پرېږده چې یوځل بیا راشي او مونږ ته وښایي چې کله هغه هلک پیدا شي د هغه روزنه څنګه وکړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_8.mp3', '', 1761754199, 1761754199),
(40338, 'Judges 13:9', 'Judges', 13, 9, 'خدای د مانوح غوښتنه قبوله کړه او په داسې حال کې چې هغه ښځه په پټي کې ناسته وه، فرښته بېرته هغې ته راغله. په هغه وخت کې د هغې مېړه مانوح د هغې سره نه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_9.mp3', '', 1761754199, 1761754199),
(40339, 'Judges 13:10', 'Judges', 13, 10, 'نو هغه په منډه خپل مېړه ته ورغله او ویې ویل: «هغه سړی چې هغه ورځ ماته ښکاره شوی ؤ، هغه بیا راغلی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_10.mp3', '', 1761754199, 1761754199),
(40340, 'Judges 13:11', 'Judges', 13, 11, 'مانوح د خپلې ښځې سره روان شو او هغه سړي ته ورغی او پوښتنه یې ترې وکړه: «ایا ته هغه سړی یې چې زما د ښځې سره دې خبرې کړې وې؟» هغه په ځواب کې وویل: «هو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_11.mp3', '', 1761754199, 1761754199),
(40341, 'Judges 13:12', 'Judges', 13, 12, 'بیا مانوح وویل: «کله چې ستا خبرې رښتیا شي، هغه هلک باید څه وکړي؟ هغه باید څه ډول ژوند وکړي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_12.mp3', '', 1761754199, 1761754199),
(40342, 'Judges 13:13', 'Judges', 13, 13, 'د څښتن فرښتې په ځواب کې وویل: «ستا ښځه باید زما په ټولو خبرو باندې عمل وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_13.mp3', '', 1761754199, 1761754199),
(40343, 'Judges 13:14', 'Judges', 13, 14, 'هر شی چې د انګورو څخه جوړیږي هغه باید ونه خوري. هغه دې نه شراب څښي او نه دې حرام شیان خوري. هرڅه چې مې ورته ویلي دي په هغو باندې دې عمل وکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_14.mp3', '', 1761754199, 1761754199),
(40344, 'Judges 13:17', 'Judges', 13, 17, 'مانوح وویل: «ستا نوم څه دی؟ کله چې ستا خبرې رښتیا شي، نو بیا به مونږ ستا عزت کوو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_17.mp3', '', 1761754199, 1761754199),
(40345, 'Judges 13:18', 'Judges', 13, 18, 'فرښتې پوښتنه وکړه: «ته ولې غواړې چې زما نوم وپېژنې؟ ځکه چې زما د نوم په معنی باندې پوهېدل د انسان د قدرت څخه وتلی کار دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_18.mp3', '', 1761754199, 1761754199),
(40346, 'Judges 13:19', 'Judges', 13, 19, 'نو مانوح یو سېرلی او یو څه غلې دانې واخیستلې او په یو ګټ باندې یې څښتن ته وړاندې کړل. څښتن د مانوح او د هغه د ښځې د سترګو په وړاندې داسې عجیبه کار وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_19.mp3', '', 1761754199, 1761754199),
(40347, 'Judges 13:22', 'Judges', 13, 22, 'مانوح خپلې ښځې ته وویل: «مونږ به په رښتیا سره مړه شو، ځکه چې خدای مو لیدلی دی!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_22.mp3', '', 1761754199, 1761754199),
(40348, 'Judges 13:23', 'Judges', 13, 23, 'خو د هغه ښځې په ځواب کې وویل: «که چېرې څښتن زمونږ د وژلو نیت درلودلی، نو هغه به زمونږ نذرانې قبولې کړې نه وای او نه به یې مونږ ته دا ټول شیان ښودلي وای او نه به یې مونږ ته په دې وخت کې دا خبرې کړې وای.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_23.mp3', '', 1761754199, 1761754199),
(40349, 'Judges 13:24', 'Judges', 13, 24, 'نو هغې ښځې یو هلک وزېږاوه او په هغه باندې یې شمشون نوم کېښود. هغه لوی شو او څښتن هغه ته برکت ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_24.mp3', '', 1761754199, 1761754199),
(40350, 'Judges 13:25', 'Judges', 13, 25, 'او هغه وخت چې شمشون د زرعه او اشتاول ترمنځ د دان په کمپ کې ؤ، د څښتن روح د هغه په قوي کولو پیل وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges13_verse_25.mp3', '', 1761754199, 1761754199),
(40351, 'Micah 7:1', 'Micah', 7, 1, 'افسوس دې وي زما په حال! ځکه زه د هغه وږي کس په شان یم چې د فصل د راټولېدو نه وروسته په ونو کې ورته مېوه او په تاکونو کې ورته انګور نه پیدا کیږي. ځکه چې انګور او خوندور او پاخه انځران پاتې شوي نه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_1.mp3', '', 1761754199, 1761754199),
(40352, 'Micah 7:2', 'Micah', 7, 2, 'ټول خدای ته وفادار خلک ورک شوي دي او هېڅ یو صادق سړی د ځمکې په مخ نه دی پاتې. هرڅوک د دې موقعې په انتظار کې دی چې قتل وکړي او هرڅوک خپل خلک په دام کې راګېروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_2.mp3', '', 1761754199, 1761754199),
(40353, 'Micah 7:3', 'Micah', 7, 3, 'هغوی ټول په بدو کارونو کې ماهران دي. مامورین او قاضیان رشوتونه اخلي. د غټو او قدرمندو خلکو چې هرڅه زړه غواړي، هغوی ته یې وایي او هغوی په ګډه سره دسیسې جوړوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_3.mp3', '', 1761754199, 1761754199),
(40354, 'Micah 7:4', 'Micah', 7, 4, 'حتی د هغوی ډېر ښه خلک هم لکه د اغزو په شان او ایمانداره خلک یې لکه د کرکڼو په شان دي. هغه ورځ رارسېدلې ده چې خدای به هغو خلکو ته سزا ورکوي، لکه څنګه یې چې هغوی د خپلو پهره‌دارانو یعنې پیغمبرانو په وسیله خبر کړي وو. اوس هغوی وارخطا دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_4.mp3', '', 1761754199, 1761754199),
(40355, 'Micah 7:5', 'Micah', 7, 5, 'په خپل ګاونډي باندې اعتبار مه کوه او حتی په خپل دوست باندې هم یقین مه کوه. حتی خپلې ګرانې ښځې ته هم چې کومه خبره کوې، نو په هغې کې احتیاط کوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_5.mp3', '', 1761754199, 1761754199),
(40356, 'Micah 7:6', 'Micah', 7, 6, 'په دې زمانه کې زوی خپل پلار ته په سپکه سترګه ګوري، لور د خپلې مور سره مخالفت کوي او انږور د خپلې خواښې سره ناندرۍ وهي. د یو سړي د خپلې کورنۍ غړي د هغه دښمنان شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_6.mp3', '', 1761754199, 1761754199),
(40357, 'Micah 7:7', 'Micah', 7, 7, 'خو زه به څښتن ته سترګې په لاره یم. زه به خدای ته په صبر سره انتظار کوم چې هغه به مې وژغوري. زما خدای به زما دعا قبوله کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_7.mp3', '', 1761754199, 1761754199),
(40358, 'Micah 7:8', 'Micah', 7, 8, 'ای زمونږ دښمنانو، بېځایه په مونږ باندې مه خوشحالېږئ. ځکه کله چې مونږ ولوېږو، نو بېرته به راپورته شو. کله چې مونږ په تیاره کې یو، نو څښتن به زمونږ دپاره رڼا وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_8.mp3', '', 1761754199, 1761754199),
(40359, 'Micah 7:9', 'Micah', 7, 9, 'مونږ د څښتن په وړاندې ګناه کړې ده، نو مونږ باید تر یو وخته پورې د هغه قهر وزغمو. خو وروسته به هغه زمونږ دفاع وکړي او زمونږ دښمنانو ته به د هغو بدیو په سبب چې زمونږ سره یې کړي دي، سزا ورکړي. هغه به مونږ د تیارې نه رڼا ته راولي او مونږ به د هغه عدالت ووینو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_9.mp3', '', 1761754199, 1761754199),
(40360, 'Micah 7:10', 'Micah', 7, 10, 'نو زمونږ دښمنان به دا وګوري او رسوا به شي، یعنې هغو دښمنانو چې مونږ ته به یې پېغور راکاوه او پوښتنه به یې کوله: «چېرته دی ستاسو څښتن خدای؟» مونږ به وګورو چې هغوی به د ماتې سره مخامخ شي او د خټو په شان به په کوڅو کې تر‌پښو لاندې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_10.mp3', '', 1761754199, 1761754199),
(40361, 'Micah 7:11', 'Micah', 7, 11, 'ای د اورشلیم خلکو، ستاسو د ښار د دېوالونو د بیا جوړونې وخت راروان دی. په هغه وخت کې به ستاسو سیمه پراخه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_11.mp3', '', 1761754199, 1761754199),
(40362, 'Micah 7:12', 'Micah', 7, 12, 'ستاسو خلک به د هرځای نه بېرته تاسو ته راشي یعنې په ختیځ کې د آشور نه، په جنوب کې د مصر د ښارونو نه، د فرات د سیمې نه او د لېرې لېرې بحیرو او غرونو څخه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_12.mp3', '', 1761754199, 1761754199),
(40363, 'Micah 7:13', 'Micah', 7, 13, 'خو نور هېوادونه به د هغې د اوسېدونکو د بدکارۍ له امله په دښته باندې بدله شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_13.mp3', '', 1761754199, 1761754199),
(40364, 'Micah 7:14', 'Micah', 7, 14, 'ای څښتنه، د خپل قوم شپون اوسه یعنې هغه قوم چې تا د خپل ځان دپاره غوره کړی دی. که څه هم هغوی په ځنګل کې یوازې اوسیږي، خو شاوخوا ته یې حاصلخېزه ځمکه ده. پرېږده چې هغوی لاړ شي او د باشان او جلعاد په شنو څړځایونو کې د پخوا زمانو په شان وڅریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_14.mp3', '', 1761754199, 1761754199),
(40365, 'Micah 7:15', 'Micah', 7, 15, 'څښتن وایي: «زه به هغوی ته خپلې معجزې وښایم لکه څنګه چې ما په هغه وخت کې وښودلې چې کله مې تاسو د مصر نه راویستلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_15.mp3', '', 1761754199, 1761754199),
(40366, 'Micah 7:16', 'Micah', 7, 16, 'نور قومونه به دا وګوري او د هغه ټول قوت سره سره چې دوی یې لري، وبه شرمیږي. هغوی به له وېرې خپله خوله پټه کړي او څه به نه اوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_16.mp3', '', 1761754199, 1761754199),
(40367, 'Micah 7:17', 'Micah', 7, 17, 'هغوی به لکه د مارانو په شان په خاورو کې په سینه باندې ښوییږي او خاورې به څټي. هغوی به د خپلو جنګي کلاګانو نه راوځي او رپیږي به. هغوی به له وېرې ما څښتن ته چې ستاسو خدای یم راوګرځي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_17.mp3', '', 1761754199, 1761754199),
(40368, 'Micah 7:18', 'Micah', 7, 18, 'ای څښتنه، ستا په شان بل خدای نشته. ته د خپلو هغو خلکو ګناهونه او سرکښي بخښې چې د جلاوطنۍ نه وروسته ژوندي پاتې شوي دي. ستا قهر به د تل دپاره نه وي، خو ته مونږ ته د خپلې تلپاتې مینې په ښودلو باندې خوشحالېږې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_18.mp3', '', 1761754199, 1761754199),
(40369, 'Micah 7:19', 'Micah', 7, 19, 'ته به یوځل بیا په مونږ باندې مهربانه شې. ته به زمونږ ګناهونه تر‌پښو لاندې کړې او هغه به د بحیرې تل ته وروغورځوې!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_19.mp3', '', 1761754199, 1761754199),
(40370, 'Micah 7:20', 'Micah', 7, 20, 'ته به خپله وفاداري او تلپاتې مینه مونږ ته یعنې د ابراهیم او یعقوب اولادې ته وروښایې، لکه څنګه چې دې په پخوا زمانو کې زمونږ د نیکونو سره وعده کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah7_verse_20.mp3', '', 1761754199, 1761754199),
(40371, 'Genesis 31:1', 'Genesis', 31, 1, 'یعقوب واورېدل چې د لابان زامنو ویلي دي چې «هرڅه چې زمونږ د پلار سره وو، هغه یعقوب واخیستل او دا ټوله شتمني یې زمونږ د پلار د شتمنۍ څخه لاسته راوړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_1.mp3', '', 1761754199, 1761754199),
(40372, 'Genesis 31:2', 'Genesis', 31, 2, 'هغه ولیدل چې د لابان چلند د هغه سره د پخوا په شان دوستانه نه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_2.mp3', '', 1761754199, 1761754199),
(40373, 'Genesis 31:3', 'Genesis', 31, 3, 'بیا څښتن یعقوب ته وویل: «بېرته خپل پلرني وطن او خپلو خپلوانو ته لاړ شه. زه به ستا سره مل یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_3.mp3', '', 1761754199, 1761754199),
(40374, 'Genesis 31:4', 'Genesis', 31, 4, 'نو یعقوب راحیل او لیې ته خبر ولېږه چې صحرا ته یعنې هغه ځای ته راشي چې د هغه رمې په کې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_4.mp3', '', 1761754199, 1761754199),
(40375, 'Genesis 31:5', 'Genesis', 31, 5, 'یعقوب هغوی ته وویل: «زه وینم چې ستاسو د پلار چلند زما سره د پخوا په شان دوستانه نه دی، خو زما د پلار خدای زما سره مل دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_5.mp3', '', 1761754199, 1761754199),
(40376, 'Genesis 31:6', 'Genesis', 31, 6, 'تاسې دواړه پوهېږئ چې ما په خپل ټول قوت سره ستاسو د پلار خدمت کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_6.mp3', '', 1761754199, 1761754199),
(40377, 'Genesis 31:7', 'Genesis', 31, 7, 'سره له دې چې ستاسو پلار زما سره ټګي کړې ده او لس ځله یې زما مزدوري بدله کړه، خو خدای هغه پرېنښود چې ماته زیان راورسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_7.mp3', '', 1761754199, 1761754199),
(40378, 'Genesis 31:8', 'Genesis', 31, 8, 'کله چې به لابان وویل: ‹خالداره وزې دې ستا مزدوري وي،› نو ټولو رمو به خالداره بچي زېږول او چې کله به یې وویل: ‹خطداره دې ستا وي،› نو ټولو رمو به خطداره بچي زېږول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_8.mp3', '', 1761754199, 1761754199),
(40379, 'Genesis 31:9', 'Genesis', 31, 9, 'نو خدای ستاسو د پلار څخه رمې واخیستلې او ماته یې راکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_9.mp3', '', 1761754199, 1761754199),
(40380, 'Genesis 31:10', 'Genesis', 31, 10, 'د بچیو د زېږولو په موسم کې ما یو خوب ولیده. سترګې مې پورته کړې او ومې لیدل هغه سېرلي چې د وزو سره جوړه کېدل خطداره او خالداره وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_10.mp3', '', 1761754199, 1761754199),
(40381, 'Genesis 31:11', 'Genesis', 31, 11, 'د خدای فرښتې په خوب کې راته وویل: ‹ای یعقوبه!› ما ځواب ورکړ: ‹زه حاضر یم.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_11.mp3', '', 1761754199, 1761754199),
(40382, 'Genesis 31:12', 'Genesis', 31, 12, 'هغه وویل: ‹سترګې پورته کړه او وګوره. هغه ټول سېرلي چې د وزو سره جوړه کیږي ټول خالداره او خطداره دي، ځکه هرڅه چې لابان ستا سره کړي دي، هغه مې لیدلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_12.mp3', '', 1761754199, 1761754199),
(40383, 'Genesis 31:13', 'Genesis', 31, 13, 'زه هماغه خدای یم چې په بیت‌ییل کې درښکاره شوم. په هغه ځای کې چې تا په هغې تیږې باندې د زیتونو تېل واچول او زما دپاره دې نذر ورکړ. اوس دا خاوره پرېږده او هغه وطن ته لاړ شه چې ته په کې پیدا شوی یې.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_13.mp3', '', 1761754199, 1761754199),
(40384, 'Genesis 31:14', 'Genesis', 31, 14, 'راحیل او لیه یعقوب ته په ځواب کې وویل: «مونږ ته د خپل پلار څخه هېڅ شی په میراث کې راپاتې نه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_14.mp3', '', 1761754199, 1761754199),
(40385, 'Genesis 31:15', 'Genesis', 31, 15, 'هغه زمونږ سره د پردیو په شان چلند کوي. هغه مونږ خرڅې کړې یو او هغه پیسې چې زمونږ دپاره هغه ته ورکړل شوې وې، ټولې یې مصرف کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_15.mp3', '', 1761754199, 1761754199),
(40386, 'Genesis 31:16', 'Genesis', 31, 16, 'هغه ټول مال او دولت چې خدای زمونږ د پلار څخه اخیستی دی، هغه زمونږ او زمونږ د اولادونو دی. نو هرڅه چې خدای درته ویلي دي، هماغسې وکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_16.mp3', '', 1761754199, 1761754199),
(40387, 'Genesis 31:17', 'Genesis', 31, 17, 'نو یعقوب خپل اولادونه او خپلې ښځې په اوښانو باندې سپرې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_17.mp3', '', 1761754199, 1761754199),
(40388, 'Genesis 31:18', 'Genesis', 31, 18, 'هغه خپل ټول حیوانات مخکې کړل او هغه څه چې په بین‌النهرین کې یې ګټلي وو ټول واخیستل، ترڅو خپل پلار اسحاق ته چې په کنعان کې ؤ، لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_18.mp3', '', 1761754199, 1761754199),
(40389, 'Genesis 31:19', 'Genesis', 31, 19, 'په هغه وخت کې چې لابان د خپلو پسونو د سکولولو دپاره تللی ؤ، راحیل د خپل پلار د کورنۍ بتان غلا کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_19.mp3', '', 1761754199, 1761754199),
(40390, 'Genesis 31:20', 'Genesis', 31, 20, 'یعقوب لابان وغولاوه، ځکه چې هغه یې په دې باندې خبر نه کړ چې دی د تللو نیت لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_20.mp3', '', 1761754199, 1761754199),
(40391, 'Genesis 31:21', 'Genesis', 31, 21, 'هرڅه چې هغه درلودل هغه یې واخیستل او وتښتېده. هغوی د فرات د سیند څخه تېر شول او د جلعاد د غرنۍ سیمې په لور روان شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_21.mp3', '', 1761754199, 1761754199),
(40392, 'Genesis 31:22', 'Genesis', 31, 22, 'په درېمه ورځ لابان ته خبر ورسېده چې یعقوب تښتېدلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_22.mp3', '', 1761754199, 1761754199),
(40393, 'Genesis 31:23', 'Genesis', 31, 23, 'هغه خپل خپلوان د ځان سره واخیستل او اووه ورځې یې په هغه پسې لاره ووهله او د جلعاد په غرنۍ سیمه کې هغه ته ورورسېد.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_23.mp3', '', 1761754199, 1761754199),
(40394, 'Genesis 31:24', 'Genesis', 31, 24, 'خو خدای د شپې په خوب کې لابان ته ښکاره شو او هغه ته یې وویل: «پام کوه چې یعقوب ته هېڅ ونه وایې. نه ورته ښه ووایې او نه بد.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_24.mp3', '', 1761754199, 1761754199),
(40395, 'Genesis 31:25', 'Genesis', 31, 25, 'یعقوب د جلعاد په غرنۍ سیمه کې خپلې خېمې ودرولې وې چې لابان ورورسېد او هغه هم د خپلو خپلوانو سره په هغه ځای کې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_25.mp3', '', 1761754199, 1761754199),
(40396, 'Genesis 31:26', 'Genesis', 31, 26, 'لابان یعقوب ته وویل: «څه دې وکړل؟ زه دې وغولولم او زما لورګانې دې د جنګي اسیرانو په شان بوتللې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_26.mp3', '', 1761754199, 1761754199),
(40397, 'Genesis 31:27', 'Genesis', 31, 27, 'ولې دې زه وغولولم او په پټه وتښتېدلې؟ ولې دې زه خبر نه کړم چې تاسو مې په خوشحالۍ، په سندرو او د چمبو او رباب په ساز سره رخصت کړي وای.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_27.mp3', '', 1761754199, 1761754199),
(40398, 'Genesis 31:28', 'Genesis', 31, 28, 'زه دې پرېنښودم چې خپل لمسیان او لورګانې ښکل کړم او خدای پاماني ورسره وکړم. بې‌عقله کار دې وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_28.mp3', '', 1761754199, 1761754199),
(40399, 'Genesis 31:29', 'Genesis', 31, 29, 'زه دا توان لرم چې زیان درورسوم، خو ستا د پلار خدای تېره شپه ماته وویل چې پام کوه چې یعقوب ته هېڅ ونه وایې. نه ورته ښه ووایې او نه بد.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_29.mp3', '', 1761754199, 1761754199),
(40400, 'Genesis 31:30', 'Genesis', 31, 30, 'اوس ته روان یې، ځکه چې تا دا ارمان درلود چې بېرته د خپل پلار کور ته لاړ شې، نو زما بتان دې ولې غلا کړي دي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_30.mp3', '', 1761754199, 1761754199),
(40401, 'Genesis 31:31', 'Genesis', 31, 31, 'یعقوب لابان ته په ځواب کې وویل: «زه ووېرېدم، ځکه چې ما فکر وکړ چې خپلې لورګانې به په زور زما څخه واخلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_31.mp3', '', 1761754199, 1761754199),
(40402, 'Genesis 31:32', 'Genesis', 31, 32, 'خو که د هرچا سره دې خپل بتان پیدا کړل، هغه دې ووژل شي. زمونږ د خپلوانو په مخکې یې وګوره. که چېرې ستا کوم شی زمونږ سره وي، خپل ځان ته یې واخله.» خو یعقوب په دې باندې نه پوهېده چې راحیل هغه بتان غلا کړي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_32.mp3', '', 1761754199, 1761754199),
(40403, 'Genesis 31:33', 'Genesis', 31, 33, 'نو لابان د یعقوب خېمې ته ننوت او هغه یې ولټوله. بیا د لیه خېمې ته او د دواړو وینځو خېمو ته ننوت او هېڅ یې پیدا نه کړل. بیا هغه د راحیل خېمې ته ننوت.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_33.mp3', '', 1761754199, 1761754199),
(40404, 'Genesis 31:34', 'Genesis', 31, 34, 'راحیل بتان د اوښ د زین لاندې ایښي وو او ورباندې ناسته وه. لابان ټوله خېمه ولټوله، هېڅ یې ونه موندل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_34.mp3', '', 1761754199, 1761754199),
(40405, 'Genesis 31:35', 'Genesis', 31, 35, 'راحیل خپل پلار ته وویل: «پلاره، خفه نه شې. زه ستا په مخکې نه شم پاڅېدلی، ځکه چې په ما باندې میاشتینۍ ناروغي راغلې ده.» لابان خېمه ولټوله، خو بتان یې پیدا نه کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_35.mp3', '', 1761754199, 1761754199),
(40406, 'Genesis 31:36', 'Genesis', 31, 36, 'یعقوب په قهر شو او د لابان سره یې شخړه وکړه او د هغه څخه یې پوښتنه وکړه: «ما څه جرم کړی دی؟ او کومه خطا مې کړې ده چې راپسې یې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_36.mp3', '', 1761754199, 1761754199),
(40407, 'Genesis 31:37', 'Genesis', 31, 37, 'اوس چې تا زما ټول سامان ولټاوه که د خپل کور سامان دې موندلی وي، دلته یې زما د خپلوانو او ستا د خپلوانو په مخکې کېږده او پرېږده چې هغوی دا پرېکړه وکړي چې زمونږ دواړو څخه کوم یو په حقه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_37.mp3', '', 1761754199, 1761754199),
(40408, 'Genesis 31:38', 'Genesis', 31, 38, 'شل کاله کیږي چې زه ستا سره وم. ستا مېږو او وزو بچي زیان نه کړل او ستا د رمو څخه مې یو پسه هم نه دی خوړلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_38.mp3', '', 1761754199, 1761754199),
(40409, 'Genesis 31:39', 'Genesis', 31, 39, 'هغه حیوانات چې وحشي ځناورو به داړلي وو، هغه مې نه دي راوړي. د هغوی تاوان مې په خپل ځان منلی دی او هغه چې د ورځې یا به د شپې غلا شوي وو، د هغو بیه به دې زما څخه غوښتله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_39.mp3', '', 1761754199, 1761754199),
(40410, 'Genesis 31:40', 'Genesis', 31, 40, 'دا زما حال ؤ چې د ورځې په ګرمۍ او د شپې په یخنۍ کې به ځورېدلم او خوب مې نه شو کولای.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_40.mp3', '', 1761754199, 1761754199);